extern std::complex<double> M2bit2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);

extern "C" {
  extern std::complex<double> M2bit2_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb);
