#include <M2bit2.hpp>

#include <cmath>
#include <complex>
#include <FArray.hpp>
#include <mxpart_mod.hpp>

using namespace mxpart_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq.7.3
std::complex<double> M2bit2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
  };
  auto zab = [&za, &zb](int i1, int i2, int i3) {
      return za(i1,i2)*zb(i2,i3);
  };

  // @coverage-probe
  std::complex<double> M2bit2_value =
      -zab(j3,j2,j1)*std::pow(zab2(j5,j1,j2,j3), 2)
      / (zb(j2,j3)*za(j5,j6)*std::pow(zab2(j4,j1,j2,j3), 2));

  return M2bit2_value;
}

extern "C" {
  std::complex<double> M2bit2_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return M2bit2(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
